PROGRAM TankControl
VAR_INPUT
    Low_Level_Sensor : BOOL;
    High_Level_Sensor : BOOL;
    Start_Button : BOOL;
    Stop_Button : BOOL;
END_VAR
VAR_OUTPUT
    Fill_Pump : BOOL;
END_VAR
Fill_Pump := (Start_Button OR NOT High_Level_Sensor) AND NOT Stop_Button;
END_PROGRAM

PROGRAM TrafficLightCycle
VAR_OUTPUT
    Red_Light : BOOL;
    Yellow_Light : BOOL;
    Green_Light : BOOL;
END_VAR
VAR
    TP_Red : TP;
    TP_Green : TP;
    TP_Yellow : TP;
END_VAR
TP_Red(IN := TRUE, PT := T#5s);
TP_Green(IN := TP_Red.Q, PT := T#5s);
TP_Yellow(IN := TP_Green.Q, PT := T#2s);
Red_Light := TP_Red.Q;
Green_Light := TP_Green.Q;
Yellow_Light := TP_Yellow.Q;
END_PROGRAM

PROGRAM MotorControlWithFaultHandling
VAR_INPUT
    Start_Button : BOOL;
    Stop_Button : BOOL;
    Overload_Trip : BOOL;
    Reset_Button : BOOL;
END_VAR
VAR_OUTPUT
    Motor_Run : BOOL;
    Fault_Lamp : BOOL;
END_VAR
Motor_Run := Start_Button AND NOT Stop_Button;
Motor_Run := Motor_Run AND NOT Overload_Trip;
Fault_Lamp := Overload_Trip OR Fault_Lamp;
IF Reset_Button THEN
    Fault_Lamp := FALSE;
END_IF;
Motor_Run := Motor_Run AND NOT Fault_Lamp;
END_PROGRAM

PROGRAM FillingCycleControl
VAR_INPUT
    Start_Button : BOOL;
    Stop_Button : BOOL;
    Bottle_Present : BOOL;
    Level_Sensor : BOOL;
END_VAR
VAR_OUTPUT
    Fill_Valve : BOOL;
END_VAR
IF Stop_Button THEN
    Fill_Valve := FALSE;
    Bottle_Count := 0;
ELSIF Start_Button AND NOT Fill_Valve THEN
    Fill_Valve := Bottle_Present AND NOT Level_Sensor;
END_IF;
IF Fill_Valve THEN
    Bottle_Count := Bottle_Count + 1;
END_IF;
END_PROGRAM

PROGRAM SiloControl
VAR_INPUT
    Low_Level_Sensor : BOOL;
    High_Level_Sensor : BOOL;
    Auto_Mode : BOOL;
END_VAR
VAR_OUTPUT
    Auger_Motor : BOOL;
    High_Alarm : BOOL;
END_VAR
VAR
    TON_High : TON;
END_VAR
TON_High(IN := High_Level_Sensor AND NOT Low_Level_Sensor, PT := T#10s);
Auger_Motor := Auto_Mode AND NOT High_Level_Sensor;
High_Alarm := TON_High.Q;
END_PROGRAM

PROGRAM SafetyControl
VAR_INPUT
    Start_Button : BOOL;
    Stop_Button : BOOL;
    E_Stop : BOOL;
    Reset_Button : BOOL;
END_VAR
VAR_OUTPUT
    Motor_Run : BOOL;
    EStop_Lamp : BOOL;
END_VAR
Motor_Run := (Start_Button AND NOT Stop_Button OR NOT E_Stop) AND Reset_Button;
EStop_Lamp := E_Stop;
END_PROGRAM

PROGRAM ConveyorControl
VAR_INPUT
    Start_Button : BOOL;
    Stop_Button : BOOL;
    Speed_Select : BOOL;
    Low_Speed_Set : INT;
    High_Speed_Set : INT;
END_VAR
VAR_OUTPUT
    Conveyor_Speed : INT;
    Running_Lamp : BOOL;
END_VAR
IF Stop_Button THEN
    Conveyor_Speed := 0;
    Running_Lamp := FALSE;
ELSIF Start_Button THEN
    Conveyor_Speed := Low_Speed_Set + High_Speed_Set;
    Running_Lamp := TRUE;
END_IF;
END_PROGRAM

PROGRAM door_control
VAR_INPUT
    Open_Button : BOOL;
    Close_Button : BOOL;
    Open_Limit : BOOL;
    Closed_Limit : BOOL;
    Obstacle_Sensor : BOOL;
END_VAR
VAR_OUTPUT
    Door_Motor_Open : BOOL;
    Door_Motor_Close : BOOL;
END_VAR
VAR
    State : INT;
    R_TRIG0 : R_TRIG;
    _TMP_AND5_OUT : BOOL;
END_VAR
R_TRIG0(CLK := Open_Button);
IF R_TRIG0.Q THEN
    State := 1;
ELSIF Close_Button THEN
    State := 2;
END_IF;
CASE State OF
    1:
        IF Open_Limit THEN
            State := 0;
        END_IF;
        Door_Motor_Open := TRUE;
        Door_Motor_Close := FALSE;
    2:
        IF Closed_Limit THEN
            State := 0;
        END_IF;
        Door_Motor_Close := TRUE;
        Door_Motor_Open := FALSE;
    0:
        Door_Motor_Open := FALSE;
        Door_Motor_Close := FALSE;
END_CASE;
IF Obstacle_Sensor THEN
    State := 1;
END_IF;
END_PROGRAM

PROGRAM AutoCarWashCycle
VAR_INPUT
    Car_Present : BOOL;
    Start_Button : BOOL;
END_VAR
VAR_OUTPUT
    Wash_Pump : BOOL;
    Rinse_Valve : BOOL;
    Dryer_Fan : BOOL;
    Cycle_Complete : BOOL;
END_VAR
VAR
    TON_Wash : TON;
    TON_Rinse : TON;
    TON_Dry : TON;
END_VAR
Wash_Pump := FALSE;
Rinse_Valve := FALSE;
Dryer_Fan := FALSE;
Cycle_Complete := FALSE;
IF Car_Present AND Start_Button THEN
    TON_Wash(IN := TRUE, PT := T#20s);
ELSIF TON_Wash.Q THEN
    TON_Rinse(IN := TRUE, PT := T#15s);
ELSIF TON_Rinse.Q THEN
    TON_Dry(IN := TRUE, PT := T#10s);
ELSIF TON_Dry.Q THEN
    Cycle_Complete := TRUE;
END_IF;
END_PROGRAM

PROGRAM CyclicCountingAndReset
VAR_INPUT
    box_sensor : BOOL;
END_VAR
VAR_OUTPUT
    pusher_cylinder : BOOL;
    box_count_display : INT;
END_VAR
VAR
    CTU0 : CTU;
    R_TRIG0 : R_TRIG;
    TP0 : TP;
END_VAR
R_TRIG0(CLK := box_sensor);
CTU0(CU := R_TRIG0.Q, R := FALSE, PV := 5);
TP0(IN := CTU0.Q, PT := T#1s);
pusher_cylinder := TP0.Q;
box_count_display := CTU0.CV;
END_PROGRAM

PROGRAM WeightCheckControl
VAR_INPUT
    Weight_Input : INT;
    Target_Weight : INT;
    Photo_Eye : BOOL;
END_VAR
VAR_OUTPUT
    Reject_Pusher : BOOL;
END_VAR
VAR
    Scaled_Weight : REAL;
END_VAR
Scaled_Weight := Weight_Input / 10.0;
IF NOT Photo_Eye THEN
    Reject_Pusher := FALSE;
ELSIF Scaled_Weight - Target_Weight / 10.0 < 5.0 OR Target_Weight / 10.0 + 5.0 > Scaled_Weight THEN
    Reject_Pusher := TRUE;
END_IF;
END_PROGRAM

PROGRAM program0
VAR_INPUT
    Temp_Sensor : INT;
    Setpoint : INT;
END_VAR
VAR_OUTPUT
    Heater : BOOL;
END_VAR
VAR
    last_temp : INT;
END_VAR
Heater := last_temp - Temp_Sensor <= 5 AND Setpoint - Temp_Sensor >= 5;
last_temp := Temp_Sensor;
END_PROGRAM

PROGRAM TempControl
VAR_INPUT
    Temp_Sensor : INT;
END_VAR
VAR_OUTPUT
    Fan1 : BOOL;
    Fan2 : BOOL;
END_VAR
Temp_Sensor := REAL_TO_INT(Temp_Sensor / 10.0);
Fan1 := Temp_Sensor >= 300;
Fan2 := Temp_Sensor >= 350;
END_PROGRAM

PROGRAM MotorPressureControl
VAR_INPUT
    Pressure_Sensor : INT;
END_VAR
VAR_OUTPUT
    Compressor_Motor : BOOL;
END_VAR
Compressor_Motor := Pressure_Sensor <= 80 AND NOT (Pressure_Sensor >= 120);
END_PROGRAM

PROGRAM DamperControl
VAR_INPUT
    CO2_Sensor : INT;
END_VAR
VAR_OUTPUT
    Damper_Position : REAL;
END_VAR
Damper_Position := (CO2_Sensor - 600) / 400.0 * 100.0 + 50.0;
END_PROGRAM

PROGRAM IrrigationControl
VAR_INPUT
    soil_moisture : INT;
    manual_start : BOOL;
END_VAR
VAR_OUTPUT
    irrigation_valve : BOOL;
END_VAR
VAR
    TON_valve : TON;
END_VAR
TON_valve(IN := soil_moisture < 30 OR manual_start, PT := T#10s);
irrigation_valve := TON_valve.Q;
END_PROGRAM

PROGRAM PartDetectionAndInspection
VAR_INPUT
    Part_Detect : BOOL;
    Part_Good : BOOL;
END_VAR
VAR_OUTPUT
    Reject_Cylinder : BOOL;
END_VAR
VAR
    TON_Reject : TON;
END_VAR
TON_Reject(IN := Part_Good, PT := T#500ms);
Reject_Cylinder := TON_Reject.Q;
END_PROGRAM

PROGRAM ElevatorControl
VAR_INPUT
    Call_Floor1 : BOOL;
    Call_Floor2 : BOOL;
    At_Floor1 : BOOL;
    At_Floor2 : BOOL;
END_VAR
VAR_OUTPUT
    Motor_Up : BOOL;
    Motor_Down : BOOL;
END_VAR
Motor_Up := (Call_Floor2 OR Call_Floor1) AND NOT At_Floor2;
Motor_Down := (Call_Floor2 OR Call_Floor1) AND NOT At_Floor1;
END_PROGRAM

PROGRAM CycleControl
VAR_INPUT
    Start_Cycle : BOOL;
    Part_Present : BOOL;
    Gripper_Extended : BOOL;
    Gripper_Retracted : BOOL;
END_VAR
VAR_OUTPUT
    Cylinder_Extend : BOOL;
    Gripper_Close : BOOL;
END_VAR
VAR
    TON_Grip_Dwell : TON;
END_VAR
TON_Grip_Dwell(IN := Start_Cycle AND Part_Present AND NOT Gripper_Extended, PT := T#500ms);
Cylinder_Extend := TON_Grip_Dwell.Q;
Gripper_Close := TON_Grip_Dwell.Q;
END_PROGRAM

PROGRAM SafetyCurtainControl
VAR_INPUT
    Start_Button : BOOL;
    Stop_Button : BOOL;
    Light_Curtain_Clear : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor_Run : BOOL;
    Safety_Fault_Lamp : BOOL;
END_VAR
Conveyor_Run := Start_Button AND Light_Curtain_Clear;
Safety_Fault_Lamp := NOT Light_Curtain_Clear;
END_PROGRAM

PROGRAM ConveyorControl
VAR_INPUT
    Start_Button : BOOL;
    Stop_Button : BOOL;
    Entry_Photo_Eye : BOOL;
    Exit_Photo_Eye : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor_Run : BOOL;
    Jam_Alarm : BOOL;
END_VAR
VAR
    TON_Jam_Delay : TON;
END_VAR
TON_Jam_Delay(IN := NOT Exit_Photo_Eye AND Entry_Photo_Eye, PT := T#8s);
Jam_Alarm := TON_Jam_Delay.Q;
IF Stop_Button THEN
    Conveyor_Run := FALSE;
    Jam_Alarm := FALSE;
ELSIF Start_Button THEN
    Conveyor_Run := TRUE;
END_IF;
Conveyor_Run := FALSE;
END_PROGRAM

PROGRAM PHControl
VAR_INPUT
    pH_Sensor : INT;
END_VAR
VAR_OUTPUT
    Acid_Pump : BOOL;
    Base_Pump : BOOL;
END_VAR
pH_Sensor := REAL_TO_INT(Scaled_PHSensor / 100.0);
Scaled_PHSensor := PH_Sensor * 0.01;
IF Scaled_PHSensor > 720.0 THEN
    Acid_Pump := TRUE;
ELSIF Scaled_PHSensor < 680.0 THEN
    Base_Pump := TRUE;
END_IF;
Acid_Pump := FALSE;
Base_Pump := FALSE;
END_PROGRAM

PROGRAM program0
VAR_INPUT
    Start_Button : BOOL;
    Stop_Button : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor_Run : BOOL;
END_VAR
Conveyor_Run := Start_Button AND NOT Stop_Button;
END_PROGRAM

PROGRAM conveyor_rpm_set
VAR_INPUT
    RPM_Set : INT;
    Start_Button : BOOL;
    Stop_Button : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor_Run : BOOL;
    start_light : BOOL;
END_VAR
Conveyor_Run := Start_Button AND NOT Stop_Button;
start_light := Conveyor_Run;
