PROGRAM CONVEYOR_CONTROL
VAR_INPUT
    RPM_Set : INT;
    Start_Button : BOOL;
    Stop_Button : BOOL;
    Vision_Sensor : INT;
END_VAR
VAR_OUTPUT
    Digital_Display : BOOL;
    Conveyor_Run : BOOL;
